
CREATE TABLE IF NOT EXISTS platform_accounts(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,display_name TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS platform_sessions(token_hash TEXT PRIMARY KEY,account_id TEXT REFERENCES platform_accounts(id),csrf TEXT NOT NULL,expires_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS platform_sessions_expiry ON platform_sessions(expires_at);
CREATE TABLE IF NOT EXISTS platform_reset_tokens(token_hash TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES platform_accounts(id),expires_at INTEGER NOT NULL,used_at TEXT);
CREATE TABLE IF NOT EXISTS platform_memberships(project_id TEXT NOT NULL,account_id TEXT NOT NULL REFERENCES platform_accounts(id),role TEXT NOT NULL CHECK(role IN ('owner','editor','reviewer','operator','visitor')),PRIMARY KEY(project_id,account_id));
CREATE TABLE IF NOT EXISTS platform_invites(id TEXT PRIMARY KEY,project_id TEXT NOT NULL,email TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('editor','reviewer','operator','visitor')),token_hash TEXT NOT NULL UNIQUE,expires_at INTEGER NOT NULL,status TEXT NOT NULL CHECK(status IN ('pending','accepted','revoked')),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS platform_reviews(id TEXT PRIMARY KEY,project_id TEXT NOT NULL,revision INTEGER NOT NULL CHECK(revision>=0),status TEXT NOT NULL CHECK(status IN ('pending','approved','changes_requested')),created_by TEXT NOT NULL,decided_by TEXT,created_at TEXT NOT NULL,decided_at TEXT);
CREATE TABLE IF NOT EXISTS platform_comments(id TEXT PRIMARY KEY,review_id TEXT NOT NULL REFERENCES platform_reviews(id),author_id TEXT NOT NULL,body TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS platform_connections(id TEXT PRIMARY KEY,project_id TEXT NOT NULL,name TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('mail','crm','data','payment')),endpoint TEXT NOT NULL,allowed_host TEXT NOT NULL,secret_ref TEXT NOT NULL,webhook_secret_ref TEXT NOT NULL,mapping TEXT NOT NULL CHECK(json_valid(mapping)),paused INTEGER NOT NULL CHECK(paused IN(0,1)),last_status TEXT NOT NULL,last_at TEXT);
CREATE INDEX IF NOT EXISTS platform_connections_project ON platform_connections(project_id,kind);
CREATE TABLE IF NOT EXISTS platform_outbox(id TEXT PRIMARY KEY,project_id TEXT NOT NULL,connection_id TEXT NOT NULL REFERENCES platform_connections(id),event_key TEXT NOT NULL,body TEXT NOT NULL CHECK(json_valid(body)),status TEXT NOT NULL CHECK(status IN ('pending','sending','sent','failed')),attempts INTEGER NOT NULL DEFAULT 0,next_at INTEGER NOT NULL,lease_until INTEGER NOT NULL DEFAULT 0,error_code TEXT,created_at TEXT NOT NULL,UNIQUE(connection_id,event_key));
CREATE INDEX IF NOT EXISTS platform_outbox_due ON platform_outbox(status,next_at);
CREATE TABLE IF NOT EXISTS platform_data_cache(connection_id TEXT PRIMARY KEY REFERENCES platform_connections(id),body TEXT NOT NULL CHECK(json_valid(body)),expires_at INTEGER NOT NULL,fetched_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS platform_products(id TEXT PRIMARY KEY,project_id TEXT NOT NULL,name TEXT NOT NULL,price_minor INTEGER NOT NULL CHECK(price_minor>=0),currency TEXT NOT NULL,inventory INTEGER NOT NULL CHECK(inventory>=0),active INTEGER NOT NULL CHECK(active IN(0,1)),updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS platform_products_project ON platform_products(project_id,active);
CREATE TABLE IF NOT EXISTS platform_orders(id TEXT PRIMARY KEY,project_id TEXT NOT NULL,account_id TEXT NOT NULL REFERENCES platform_accounts(id),idempotency_key TEXT NOT NULL,fingerprint TEXT NOT NULL,items TEXT NOT NULL CHECK(json_valid(items)),amount_minor INTEGER NOT NULL CHECK(amount_minor>=0),currency TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('pending','checkout_pending','paid','partially_refunded','refunded','cancelled','failed')),refunded_minor INTEGER NOT NULL DEFAULT 0 CHECK(refunded_minor>=0),provider_id TEXT,provider_payment_id TEXT,provider_sequence INTEGER NOT NULL DEFAULT -1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(project_id,account_id,idempotency_key));
CREATE INDEX IF NOT EXISTS platform_orders_project ON platform_orders(project_id,created_at DESC);
CREATE TABLE IF NOT EXISTS platform_payment_events(provider_id TEXT NOT NULL,event_id TEXT NOT NULL,order_id TEXT NOT NULL REFERENCES platform_orders(id),sequence INTEGER NOT NULL,body_hash TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(provider_id,event_id));
CREATE TABLE IF NOT EXISTS platform_payment_commands(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES platform_orders(id),command TEXT NOT NULL,amount_minor INTEGER NOT NULL CHECK(amount_minor>=0),idempotency_key TEXT NOT NULL,fingerprint TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(order_id,idempotency_key));
CREATE TABLE IF NOT EXISTS platform_resources(id TEXT PRIMARY KEY,project_id TEXT NOT NULL,name TEXT NOT NULL,capacity INTEGER NOT NULL CHECK(capacity>0),active INTEGER NOT NULL CHECK(active IN(0,1)));
CREATE TABLE IF NOT EXISTS platform_slots(id TEXT PRIMARY KEY,resource_id TEXT NOT NULL REFERENCES platform_resources(id),starts_at TEXT NOT NULL,ends_at TEXT NOT NULL,capacity INTEGER NOT NULL CHECK(capacity>0),CHECK(starts_at<ends_at),UNIQUE(resource_id,starts_at,ends_at));
CREATE TABLE IF NOT EXISTS platform_bookings(id TEXT PRIMARY KEY,project_id TEXT NOT NULL,slot_id TEXT NOT NULL REFERENCES platform_slots(id),account_id TEXT NOT NULL REFERENCES platform_accounts(id),quantity INTEGER NOT NULL CHECK(quantity>0),status TEXT NOT NULL CHECK(status IN ('confirmed','cancelled')),idempotency_key TEXT NOT NULL,fingerprint TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(project_id,account_id,idempotency_key));
CREATE INDEX IF NOT EXISTS platform_bookings_slot ON platform_bookings(slot_id,status);
CREATE TABLE IF NOT EXISTS platform_billing(project_id TEXT PRIMARY KEY,plan TEXT NOT NULL,limits TEXT NOT NULL CHECK(json_valid(limits)),updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS platform_usage(project_id TEXT NOT NULL,metric TEXT NOT NULL,period TEXT NOT NULL,value INTEGER NOT NULL CHECK(value>=0),PRIMARY KEY(project_id,metric,period));
